def giai_thua_duoi(n, acc=1):
    if n &lt;= 1:
        return acc
    return giai_thua_duoi(n - 1, acc * n)  # tail call

# Phiên bản LẶP tương đương (không tốn ngăn xếp)
def giai_thua_lap(n):
    kq = 1
    for i in range(2, n + 1):
        kq *= i
    return kq

